using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Text;
using System.Text.Json;
using System.Threading;
using codeLess.AvaloniaApp;
using codeLess.Studio;
using Xunit;

namespace codeLess.Avalonia.Tests
{
    /// <summary>
    /// Headless big-monorepo benchmark (no GUI). Skipped unless CODELESS_BENCH_MONOREPO points at a repo generated by
    /// bench/gen_monorepo.py; writes a report to CODELESS_BENCH_REPORT. Run via bench/run_monorepo_bench.sh.
    /// "old" = the previous code paths (12k-file / depth-7 walker, every file materialised as a palette entry and
    /// re-scored per keystroke, search without .gitignore), "new" = WorkspaceIgnoreRules / QuickOpenFileIndex.
    /// </summary>
    public class MonorepoScaleBench
    {
        private static readonly string[] OldExcluded =
            { ".git", "node_modules", "bin", "obj", "dist", "build", "out", ".venv", "__pycache__", ".next", "target", "packages", ".vs",
              "DerivedData", "Pods", ".gradle", ".nuxt", ".svelte-kit", "coverage", ".turbo", ".cache" };

        private static long LiveBytes()
        {
            GC.Collect(2, GCCollectionMode.Forced, true, true);
            GC.WaitForPendingFinalizers();
            GC.Collect(2, GCCollectionMode.Forced, true, true);
            return GC.GetTotalMemory(true);
        }

        private static double Median(List<double> v)
        {
            var s = v.OrderBy(x => x).ToList();
            return s.Count == 0 ? 0 : (s.Count % 2 == 1 ? s[s.Count / 2] : (s[s.Count / 2 - 1] + s[s.Count / 2]) / 2);
        }

        private static List<string> OldWalk(string root)
        {
            var mi = typeof(MainWindow).GetMethod("CollectWorkspaceFilesListRecursive", BindingFlags.NonPublic | BindingFlags.Static);
            var list = new List<string>();
            var seen = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            mi.Invoke(null, new object[] { root, new HashSet<string>(OldExcluded, StringComparer.OrdinalIgnoreCase), 0, list, seen, 12000, CancellationToken.None });
            return list;
        }

        private static List<string> NewWalk(string root, out bool capped)
        {
            var rules = new WorkspaceIgnoreRules(root, OldExcluded, true);
            return rules.EnumerateFiles(new[] { root }, WorkspaceIgnoreRules.DefaultMaxIndexedFiles, CancellationToken.None, out capped);
        }

        /// <summary>The palette's previous per-keystroke filter: score every entry, sort, take 120.</summary>
        private static List<string> OldQuickOpenFilter(List<(string Title, string Rel, string Full)> entries, string query)
        {
            string[] toks = query.Split(new[] { ' ' }, StringSplitOptions.RemoveEmptyEntries);
            return entries.Select(en =>
            {
                int total = 0;
                foreach (string t in toks)
                {
                    int byName = WorkspaceSearchEngine.ComputeFuzzySubsequenceScore(en.Title, t);
                    int byPath = t.IndexOf('/') >= 0 || byName == 0 ? WorkspaceSearchEngine.ComputeFuzzySubsequenceScore(en.Rel, t) / 2 : 0;
                    int sc = Math.Max(byName, byPath);
                    if (sc <= 0) return (en.Full, 0);
                    total += sc;
                }
                return (en.Full, total);
            }).Where(x => x.Item2 > 0).OrderByDescending(x => x.Item2).Take(120).Select(x => x.Item1).ToList();
        }

        [Fact]
        public void Run()
        {
            string repo = Environment.GetEnvironmentVariable("CODELESS_BENCH_MONOREPO");
            if (string.IsNullOrEmpty(repo) || !Directory.Exists(repo)) return; // opt-in benchmark
            string reportPath = Environment.GetEnvironmentVariable("CODELESS_BENCH_REPORT") ?? Path.Combine(Path.GetTempPath(), "cl-monorepo-bench.txt");
            int runs = int.TryParse(Environment.GetEnvironmentVariable("CODELESS_BENCH_RUNS"), out int r) ? r : 5;
            repo = Path.GetFullPath(repo).TrimEnd('/');
            var manifest = JsonDocument.Parse(File.ReadAllText(repo + ".manifest.json")).RootElement;
            string needle = manifest.GetProperty("needle").GetString();
            int needleFiles = manifest.GetProperty("needle_files").GetArrayLength();
            var qoTargets = manifest.GetProperty("quick_open_targets").EnumerateArray().Select(x => x.GetString()).ToList();
            var sb = new StringBuilder();
            void Log(string s) { sb.AppendLine(s); File.WriteAllText(reportPath, sb.ToString()); }
            Log($"repo={repo} runs={runs} files_on_disk={Directory.EnumerateFiles(repo, "*", SearchOption.AllDirectories).Count()}");

            // ---- 1. workspace walk (file list for Quick Open / indexing)
            List<string> oldFiles = null, newFiles = null;
            bool capped = false;
            var tOld = new List<double>(); var tNew = new List<double>();
            for (int i = 0; i < runs; i++)
            {
                var sw = Stopwatch.StartNew(); oldFiles = OldWalk(repo); tOld.Add(sw.Elapsed.TotalMilliseconds);
                sw.Restart(); newFiles = NewWalk(repo, out capped); tNew.Add(sw.Elapsed.TotalMilliseconds);
            }
            long m0 = LiveBytes(); var keepOld = OldWalk(repo); long mOld = LiveBytes() - m0; GC.KeepAlive(keepOld); keepOld = null;
            m0 = LiveBytes(); var keepNew = NewWalk(repo, out _); long mNew = LiveBytes() - m0; GC.KeepAlive(keepNew); keepNew = null;
            int oldIgnored = oldFiles.Count(f => f.Contains("/node_modules/") || f.Contains("/dist/") || f.Contains("/generated/") || f.EndsWith(".log"));
            int newIgnored = newFiles.Count(f => f.Contains("/node_modules/") || f.Contains("/dist/") || f.Contains("/generated/") || f.EndsWith(".log"));
            Log($"walk_old: median_ms={Median(tOld):F0} files={oldFiles.Count} gitignored_in_list={oldIgnored} quick_open_targets_reachable={qoTargets.Count(t => oldFiles.Contains(Path.Combine(repo, t)))}/{qoTargets.Count} live_mb={mOld / 1048576.0:F1}");
            Log($"walk_new: median_ms={Median(tNew):F0} files={newFiles.Count} capped={capped} gitignored_in_list={newIgnored} quick_open_targets_reachable={qoTargets.Count(t => newFiles.Contains(Path.Combine(repo, t)))}/{qoTargets.Count} live_mb={mNew / 1048576.0:F1}");

            // ---- 2. Quick Open over the full new list: old (materialise + rescore everything) vs new index
            string[] queries = { "UniqueQuokka", "QuokkaLedgerController", "invoice page", "src/utils/date", "a" };
            var tBuildOld = new List<double>(); var tBuildNew = new List<double>();
            var tQOld = new List<double>(); var tQNew = new List<double>();
            List<(string, string, string)> entries = null; QuickOpenFileIndex idx = null;
            bool foundOld = true, foundNew = true;
            for (int i = 0; i < runs; i++)
            {
                var sw = Stopwatch.StartNew();
                entries = newFiles.Select(f => (Path.GetFileName(f), LlmHarnessAndAgentEngine.GetRelativePath(repo, f).Replace('\\', '/'), f)).ToList();
                tBuildOld.Add(sw.Elapsed.TotalMilliseconds);
                sw.Restart(); idx = new QuickOpenFileIndex(repo, newFiles); tBuildNew.Add(sw.Elapsed.TotalMilliseconds);
                foreach (string q in queries)
                {
                    sw.Restart(); var a = OldQuickOpenFilter(entries, q); tQOld.Add(sw.Elapsed.TotalMilliseconds);
                    sw.Restart(); var b = idx.Search(q, 120, null); tQNew.Add(sw.Elapsed.TotalMilliseconds);
                    if (q == "UniqueQuokka") { foundOld &= a.Any(x => x.EndsWith("UniqueQuokkaWidget.tsx")); foundNew &= b.Any(h => idx.GetName(h.Index) == "UniqueQuokkaWidget.tsx"); }
                }
            }
            m0 = LiveBytes(); var keepE = newFiles.Select(f => new PaletteEntryItem { Id = "file:" + f, Category = "File", Title = Path.GetFileName(f), stringSubtitleOrPath = LlmHarnessAndAgentEngine.GetRelativePath(repo, f), FilePath = f, Execute = () => { } }).ToList(); long mE = LiveBytes() - m0; GC.KeepAlive(keepE); keepE = null;
            m0 = LiveBytes(); var keepI = new QuickOpenFileIndex(repo, newFiles); long mI = LiveBytes() - m0; GC.KeepAlive(keepI); keepI = null;
            Log($"quickopen_old: open_build_median_ms={Median(tBuildOld):F0} keystroke_median_ms={Median(tQOld):F1} keystroke_max_ms={tQOld.Max():F1} entries_live_mb={mE / 1048576.0:F1} found_deep_target={foundOld}");
            Log($"quickopen_new: open_build_median_ms={Median(tBuildNew):F0} keystroke_median_ms={Median(tQNew):F1} keystroke_max_ms={tQNew.Max():F1} index_live_mb={mI / 1048576.0:F1} found_deep_target={foundNew}");

            // ---- 3. Find in Files (walk + search), gitignore off vs on
            int defaultPar = WorkspaceSearchEngine.SearchParallelism;
            foreach (var (gi, par) in new[] { (false, 1), (true, 1), (true, defaultPar) })
            {
                WorkspaceSearchEngine.RespectGitIgnore = gi;
                WorkspaceSearchEngine.SearchParallelism = par;
                var t = new List<double>(); WorkspaceSearchResult res = null; List<string> files = null;
                for (int i = 0; i < runs; i++)
                {
                    var sw = Stopwatch.StartNew();
                    files = WorkspaceSearchEngine.EnumerateSearchFiles(new[] { repo }, repo, OldExcluded.Where(x => x != "packages"), null, null, 200000, CancellationToken.None);
                    res = WorkspaceSearchEngine.Search(repo, files, needle, new WorkspaceSearchOptions(), CancellationToken.None, null);
                    t.Add(sw.Elapsed.TotalMilliseconds);
                }
                var hitFiles = res.Matches.Select(m => m.FilePath).Distinct().ToList();
                Log($"find_in_files[gitignore={(gi ? "on" : "off")},parallel={par}]: median_ms={Median(t):F0} files_searched={files.Count} hits={res.Matches.Count} needle_files={hitFiles.Count}/{needleFiles} ignored_hits={hitFiles.Count(f => f.Contains("/node_modules/") || f.Contains("/dist/") || f.Contains("/generated/"))}");
            }
            WorkspaceSearchEngine.RespectGitIgnore = true;
            WorkspaceSearchEngine.SearchParallelism = defaultPar;

            // ---- 4. BM25 / symbol index on the 1,500-file candidate list (old list vs new list)
            foreach (var (label, list) in new[] { ("old", oldFiles), ("new", newFiles) })
            {
                var cands = list.Take(1500).ToList();
                var engine = new LlmHarnessAndAgentEngine(new IdePersistentSettings());
                long before = LiveBytes();
                var sw = Stopwatch.StartNew();
                engine.IndexWorkspace(repo, cands);
                double ms = sw.Elapsed.TotalMilliseconds;
                long delta = LiveBytes() - before;
                Log($"bm25_{label}: ms={ms:F0} candidates={cands.Count} chunks={engine.IndexedChunks.Count} live_mb={delta / 1048576.0:F1} gitignored_candidates={cands.Count(f => f.Contains("/node_modules/") || f.Contains("/generated/") || f.Contains("/dist/"))}");
                GC.KeepAlive(engine);
            }

            // ---- 5. watcher burst: 10k files created + deleted inside node_modules
            var rules = new WorkspaceIgnoreRules(repo, OldExcluded, true);
            string burstRoot = Path.Combine(repo, "node_modules", ".bench-burst");
            int events = 0, excludedEvents = 0;
            double classifyMs = 0;
            var csw = new Stopwatch();
            using (var w = new FileSystemWatcher(repo) { IncludeSubdirectories = true, InternalBufferSize = 64 * 1024, NotifyFilter = NotifyFilters.FileName | NotifyFilters.DirectoryName | NotifyFilters.LastWrite | NotifyFilters.Size })
            {
                FileSystemEventHandler h = (s, e) =>
                {
                    lock (csw)
                    {
                        events++;
                        csw.Restart();
                        if (rules.IsPathExcluded(e.FullPath, Directory.Exists(e.FullPath))) excludedEvents++;
                        classifyMs += csw.Elapsed.TotalMilliseconds;
                    }
                };
                w.Created += h; w.Deleted += h; w.Changed += h;
                w.EnableRaisingEvents = true;
                var sw = Stopwatch.StartNew();
                for (int d = 0; d < 100; d++)
                {
                    string dir = Path.Combine(burstRoot, "p" + d, "lib");
                    Directory.CreateDirectory(dir);
                    for (int f = 0; f < 100; f++) File.WriteAllText(Path.Combine(dir, "f" + f + ".js"), "module.exports=1;\n");
                }
                Directory.Delete(burstRoot, true);
                double genMs = sw.Elapsed.TotalMilliseconds;
                Thread.Sleep(3000);
                w.EnableRaisingEvents = false;
                var tw = new List<double>();
                for (int i = 0; i < 3; i++) { var s2 = Stopwatch.StartNew(); OldWalk(repo); tw.Add(s2.Elapsed.TotalMilliseconds); }
                Log($"watcher_burst: files=10000(created+deleted) gen_ms={genMs:F0} events_received={events} classified_excluded={excludedEvents} classify_total_ms={classifyMs:F0} " +
                    $"new_cost=0 re-walks (events dropped as excluded) old_cost=full re-walk per flush (~{Median(tw):F0} ms each, old walker; GUI run on 240k files saw 2 tree refreshes + 2 re-walks)");
            }
        }
    }
}
